def _z3_value(const, value):
    """Coerce a stored value to a Z3 expr of the const's sort."""
    if is_expr(value):
        return value
    if const.sort() == IntSort():
        return IntVal(value)
    return BoolVal(bool(value))


def _bindings(state, consts, key_consts=None):
    """Equalities binding consts to the concrete values stored in a State.

    Values are looked up by the names of key_consts (defaults to consts);
    pass the current-state consts as keys when binding primed constants.
    """
    equalities = []
    for i, c in enumerate(consts):
        key = str(key_consts[i]) if key_consts is not None else str(c)
        if key in state.values:
            equalities.append(c == _z3_value(c, state.values[key]))
    return equalities

