def _collect_atoms(expr):
    """Collect the Boolean leaf sub-formulas (comparison atoms) of expr."""
    atoms = []

    def visit(e):
        if is_and(e) or is_or(e) or is_not(e):
            for child in e.children():
                visit(child)
        elif is_bool(e) and not is_true(e) and not is_false(e):
            atoms.append(e)

    visit(expr)
    return atoms


